import{_ as p,a0 as o,w as r,s as c,ao as n,I as t,x as a,a1 as l,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"McFly：利用神经网络为 Bash 提供历史命令搜索功能 | LCTT x X-CMD","titleTemplate":false,"description":"McFly：利用神经网络为 Bash 提供历史命令搜索功能 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"McFly：利用神经网络为 Bash 提供历史命令搜索功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"McFly：利用神经网络为 Bash 提供历史命令搜索功能 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181210 McFly - A Replacement To ‘Ctrl-R- Bash History Search Feature","title":"McFly：利用神经网络为 Bash 提供历史命令搜索功能","tag":"201901","desc":""},"relativePath":"201901/20181210 McFly - A Replacement To ‘Ctrl-R- Bash History Search Feature.md","filePath":"[post].md"}'),h={name:"201901/20181210 McFly - A Replacement To ‘Ctrl-R- Bash History Search Feature.md"};function d(g,s,u,b,f,m){const i=o("Link");return r(),c("div",null,[s[19]||(s[19]=n('<h1 id="mcfly-利用神经网络为-bash-提供历史命令搜索功能" tabindex="-1">McFly：利用神经网络为 Bash 提供历史命令搜索功能 <a class="header-anchor" href="#mcfly-利用神经网络为-bash-提供历史命令搜索功能" aria-label="Permalink to “McFly：利用神经网络为 Bash 提供历史命令搜索功能”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/mcfly-720x340.png" alt=""></p><p>假如你在命令行模式下渡过了很长时间，那么你必定使用过或者听说过 BASH 的 <strong>反向搜索</strong> 功能，在 Bash 中执行反向搜索功能的快捷键是 <code>Ctrl+r</code>。通过使用这个特性，我们可以找到我们执行过的命令而无需再次输入它们。当然，你可以使用上下键来搜索你的 bash 命令记录，但使用 <code>Ctrl+r</code> 快捷键可以让这个搜索过程更简单快速。今天我找寻到了 Bash 历史命令搜索特性 <code>Ctrl+r</code> 的一个替代品，它就是 McFly。McFly 是一个使用 Rust 编程语言写就的简洁工具，自带一个智能的搜索引擎，用来替换默认的 <code>Ctrl+r</code> 这个 Bash 历史命令搜索功能。 McFly 提供的命令建议都是通过一个小巧的 <strong>神经网络</strong> 来实时排序给出的。</p><p>McFly 重新绑定了 <code>Ctrl+r</code> 快捷键，可以从你的 Bash 历史命令中找到所有最近执行过的命令。它通过追溯下面的信息来增强你的 shell 历史命令搜索特性：</p><ul><li>命令结束状态</li><li>当你运行命令时的时间戳</li><li>以及你运行命令的执行目录</li></ul><p>它将所有追溯的信息保存在一个 SQLite 数据库中。由于它追溯了命令的历史结束状态，所以你可以很轻易地忽略掉失败的命令。听起来很酷，对吧？</p><p>在给出一个命令建议时，它将考虑如下因素：</p><ul><li>你在哪个目录执行的这个命令，将来你很有可能在相同的目录重复这个命令</li><li>在你执行这个命令之前，执行过什么命令</li><li>你执行这个命令有多频繁</li><li>你最后执行该命令的时间</li><li>你是否在 McFly 中选择过这个命令</li><li>以及这个命令的历史结束状态。因为你很有可能不会去执行失败过的命令，对吧？</li></ul><p>McFly 维护着你的默认 Bash 历史文件，所以你可以随时停止使用它。McFly 也并不只服务于 BASH， 它也可以扩展到其他 shell 程序。</p><h3 id="安装-mcfly" tabindex="-1">安装 McFly <a class="header-anchor" href="#安装-mcfly" aria-label="Permalink to “安装 McFly”">​</a></h3>',10)),t("p",null,[s[1]||(s[1]=a("在 Linux 中，McFly 可以使用 Linuxbrew 来安装。如若你还没有安装过 Linuxbrew，那么你可以参考下面的这个链接。（LCTT 译注：从其 ",-1)),l(i,{href:"https://github.com/cantino/mcfly"},{default:e(()=>[...s[0]||(s[0]=[a("GitHub 主页",-1)])]),_:1}),s[2]||(s[2]=a("了解到也可以下载其二进制来使用。）",-1))]),t("ul",null,[t("li",null,[l(i,{href:"https://www.ostechnix.com/linuxbrew-common-package-manager-linux-mac-os-x/"},{default:e(()=>[...s[3]||(s[3]=[a("Linuxbrew：一个用于 Linux 和 Mac OS X 的通用包管理",-1)])]),_:1})])]),s[20]||(s[20]=n(`<p>一旦安装好了 Linuxbrew，运行下面的命令来安装 McFly：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew tap cantino/mcfly https://github.com/cantino/mcfly</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ brew install mcfly</span></span></code></pre></div><p>在安装完成后，你将看到下面的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>==&gt; Installing mcfly from cantino/mcfly</span></span>
<span class="line"><span>==&gt; Downloading https://github.com/cantino/mcfly/releases/download/v0.2.5/mcfly-v0</span></span>
<span class="line"><span>==&gt; Downloading from https://github-production-release-asset-2e65be.s3.amazonaws.c</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>==&gt; ONE MORE STEP! Edit ~/.bashrc and add the following:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $(brew --prefix)/opt/mcfly/mcfly.bash ]; then</span></span>
<span class="line"><span>. $(brew --prefix)/opt/mcfly/mcfly.bash</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>🍺 /home/linuxbrew/.linuxbrew/Cellar/mcfly/v0.2.5: 4 files, 3.5MB, built in 33 seconds</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/install-mcfly.png" alt=""></p><p>正如你上面看到的那样，在使用 McFly 之前我们需要再做一些配置。</p><p>将下面几行添加到你的 <code>~/.bashrc</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -f $(brew --prefix)/opt/mcfly/mcfly.bash ]; then</span></span>
<span class="line"><span>. $(brew --prefix)/opt/mcfly/mcfly.bash</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>最后，再运行下面的命令来让更改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>当你第一次执行上面的这个命令时，你的 BASH 历史将会被导入 McFly 的数据库。依据你的 bash 历史文件的大小，这个过程将花费一些时间。一旦导入完成，你讲看到下面的提示信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>McFly: Importing Bash history for the first time. This may take a minute or two...done.</span></span></code></pre></div><p>现在你就可以使用 McFly 了。</p><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h3><p>要在你的命令历史中执行搜索，只需要键入 <code>mcfly search</code> 再加上命令名的一部分，最后敲击回车键即可。Mcfly 将会基于你刚才键入的搜索查询语句给出命令建议。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly search &lt;part-of-the-command&gt;</span></span></code></pre></div><p>例如我键入了下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly search mk</span></span></code></pre></div><p>下面展示的是我 Ubuntu 机子上的示例输出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/mcfly-command-1.png" alt=""></p><p>如你所见，我已经使用过 <code>mkdir</code> 这个命令两次。假如你想从这些命令建议中执行其中之一，只需使用上下键来选择它，然后敲击<strong>回车键</strong>来执行它就可以了。假如你想编辑其中一个命令，则需要先选择它，然后敲 <code>TAB</code> 键将这个命令放置到终端中，最后在运行它之前更改它就行了。要从历史中删除已经选择的命令，按 <code>F2</code> 即可。</p><p>或者，输入下面的命令来打开历史搜索，然后输入任意一个命令或者命令的一部分来从你的历史命令中查看它提供的建议。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly search</span></span></code></pre></div><p>在你输入的同时， McFly 将会展示命令的提示。</p><p>下面是一个介绍 McFly 的简短演示视频：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/mcfly-demo.gif" alt=""></p><p>你还可以使用下面的命令来查看帮助：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly --help</span></span></code></pre></div><h3 id="移除-mcfly" tabindex="-1">移除 McFly <a class="header-anchor" href="#移除-mcfly" aria-label="Permalink to “移除 McFly”">​</a></h3><p>不喜欢 McFly，没问题！可以使用下面的命令来移除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew uninstall mcfly</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ brew untap cantino/mcfly</span></span></code></pre></div><p>最后，移除先前添加到 <code>~/.bashrc</code> 文件中的几行命令。</p><p>好了，这些就是所有了，更多精彩内容敬请期待，请保存关注！</p><p>干杯！</p><hr>`,35)),t("p",null,[s[5]||(s[5]=a("via: ",-1)),l(i,{href:"https://www.ostechnix.com/mcfly-a-replacement-to-ctrlr-bash-history-search-feature/"},{default:e(()=>[...s[4]||(s[4]=[a("https://www.ostechnix.com/mcfly-a-replacement-to-ctrlr-bash-history-search-feature/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),l(i,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[6]||(s[6]=[a("SK",-1)])]),_:1}),s[11]||(s[11]=a(" 选题：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 译者：",-1)),l(i,{href:"https://github.com/FSSlc"},{default:e(()=>[...s[8]||(s[8]=[a("FSSlc",-1)])]),_:1}),s[13]||(s[13]=a(" 校对：",-1)),l(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=a("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原创编译，",-1)),l(i,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[a("Linux中国",-1)])]),_:1}),s[18]||(s[18]=a(" 荣誉推出",-1))])])}const x=p(h,[["render",d]]);export{w as __pageData,x as default};
